def side(point1, point2, point):
	return (point2[0] - point1[0]) * (point1[1] - point[1]) - (point2[1] - point1[1]) * (point1[0] - point[0])

def print_ans(ans):
	for point in ans:
		print(point[0], point[1])

def answer(A, n):
	req = int(n / 10)
	got = 0
	ans = []
	for i in range(n):
		point = A[i]
		point_before = A[(n + i - 1) % n]
		point_after = A[(i + 1) % n]
		P = [point[0] - 1, point[1]]
		if P not in ans:
			if side(point_before, point, P) < 0 and side(point, point_after, P) < 0:
				ans.append(P)
				got += 1
				if got == req:
					print_ans(ans)
					return
	if req != got:
		for i in range(n):
			point = A[i]
			point_before = A[(n + i - 1) % n]
			point_after = A[(i + 1) % n]
			P = [point[0] + 1, point[1]]
			if P not in ans:
				if side(point_before, point, P) < 0 and side(point, point_after, P) < 0:
					ans.append(P)
					got += 1
					if got == req:
						print_ans(ans)
						return
	print(-1)
t = int(input())
for _ in range(t):
	n = int(input())
	A = [[0, 0] for _ in range(n)]
	for i in range(n):
		A[i] = list(map(int, input().split()))
	answer(A, n)
